'use strict';

// MODULES //

var tape = require( 'tape' );
var zeros = require( '@stdlib/ndarray/zeros' );
var reducedShape = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof reducedShape, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided a zero-dimensional ndarray, the function returns an empty array', function test( t ) {
	t.deepEqual( reducedShape( zeros( [] ), [] ), [], 'returns expected value' );
	t.end();
});

tape( 'if provided an empty list of dimensions, the function returns the full shape', function test( t ) {
	var x = zeros( [ 3, 2, 3 ] );
	t.deepEqual( reducedShape( x, [] ), [ 3, 2, 3 ], 'returns expected value' );
	t.end();
});

tape( 'the function returns a reduced shape', function test( t ) {
	var expected;
	var values;
	var dims;
	var out;
	var i;

	values = [
		zeros( [ 1, 2, 3, 2 ] ),
		zeros( [ 1, 2, 3, 2 ] ),
		zeros( [ 1, 2, 3, 2 ] ),
		zeros( [ 3, 2, 3 ] ),
		zeros( [ 5 ] ),
		zeros( [ 3, 3, 3 ] )
	];

	dims = [
		[ 0, 1 ],
		[ 0, 3 ],
		[ 1, 3 ],
		[ 0, 1 ],
		[ 0 ],
		[ 0, 1, 2 ]
	];

	expected = [
		[ 3, 2 ],
		[ 2, 3 ],
		[ 1, 3 ],
		[ 3 ],
		[],
		[]
	];

	for ( i = 0; i < values.length; i++ ) {
		out = reducedShape( values[ i ], dims[ i ] );
		t.deepEqual( out, expected[ i ], 'returns expected value for dims=[' + dims[ i ].join( ',' ) + ']' );
	}
	t.end();
});

tape( 'the function accepts minimal ndarray-like objects (shape)', function test( t ) {
	var expected;
	var values;
	var dims;
	var out;
	var i;

	values = [
		{
			'shape': [ 1, 2, 3, 2 ]
		},
		{
			'shape': [ 1, 2, 3, 2 ]
		},
		{
			'shape': [ 3, 3, 3 ]
		},
		{
			'shape': [ 5, 10 ]
		}
	];

	dims = [
		[ 0, 1 ],
		[ 2 ],
		[ 1 ],
		[ 0 ]
	];

	expected = [
		[ 3, 2 ],
		[ 1, 2, 2 ],
		[ 3, 3 ],
		[ 10 ]
	];

	for ( i = 0; i < values.length; i++ ) {
		out = reducedShape( values[ i ], dims[ i ] );
		t.deepEqual( out, expected[ i ], 'returns expected value for dims=[' + dims[ i ].join( ',' ) + ']' );
	}
	t.end();
});

tape( 'the function reduces a single dimension', function test( t ) {
	var x = zeros( [ 2, 3, 4, 5 ] );

	t.deepEqual( reducedShape( x, [ 0 ] ), [ 3, 4, 5 ], 'returns expected value' );
	t.deepEqual( reducedShape( x, [ 1 ] ), [ 2, 4, 5 ], 'returns expected value' );
	t.deepEqual( reducedShape( x, [ 2 ] ), [ 2, 3, 5 ], 'returns expected value' );
	t.deepEqual( reducedShape( x, [ 3 ] ), [ 2, 3, 4 ], 'returns expected value' );
	t.end();
});

tape( 'the function reduces all dimensions', function test( t ) {
	var x = zeros( [ 2, 3, 4 ] );

	t.deepEqual( reducedShape( x, [ 0, 1, 2 ] ), [], 'returns expected value' );
	t.end();
});
